alter table public.profiles enable row level security;

-- Comments
comment on column public.profiles.username is 'N38 (OS-W34): lowercase a-z, 0-9 and _, 3 to 30 characters; NULL until onboarding chooses one, and again once an account is deleted. Not reserved, not retired (private.username_tombstones). Set once.';
comment on column public.profiles.main_car_id is 'The car this member actually means. Drives featured car, default banner, car order, Garage focus and the first marketplace vehicle suggestion. Null is ordinary — readers fall back to newest-first.';
comment on column public.profiles.store_note is 'One short line above the member''s parts grid (P-8). Voice, not policy — max 180 chars, enforced below.';
comment on column public.profiles.default_offer_floor_pct is 'Seller default (P-9): the lowest share of the asking price they will consider, as a percentage. Prefills the sell form; never changes a live listing.';
comment on column public.profiles.country is 'ISO-3166-1 alpha-2. Coarse on purpose — Local needs the right ballpark, not a town.';
comment on column public.profiles.region is 'A region within the country (state, county, prefecture). Free text against src/lib/geo/regions.ts.';
comment on column public.profiles.agent_mode is 'AG-7: how far the member''s agent may go — off, suggest (no mandates), act (20261107170000). Owner-written; no client select grant.';
comment on column public.profiles.payout_details_submitted is 'Stripe account.details_submitted for the seller''s connected account, written only by the Connect sync (20261108100000).';
comment on column public.profiles.payout_restricted_at is 'Set when a sale is 14 days old and the seller''s payouts still aren''t enabled; cleared when they are (20261108100000).';

-- Constraints
alter table public.profiles add constraint profiles_agent_mode_check CHECK (agent_mode = ANY (ARRAY['off'::text, 'suggest'::text, 'act'::text]));
alter table public.profiles add constraint profiles_country_check CHECK (country IS NULL OR country ~ '^[A-Z]{2}$'::text);
alter table public.profiles add constraint profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.profiles add constraint profiles_main_car_id_fkey FOREIGN KEY (main_car_id) REFERENCES public.cars(id) ON DELETE SET NULL;
alter table public.profiles add constraint profiles_offer_floor_pct_check CHECK (default_offer_floor_pct IS NULL OR default_offer_floor_pct >= 10 AND default_offer_floor_pct <= 100);
alter table public.profiles add constraint profiles_pkey PRIMARY KEY (id);
alter table public.profiles add constraint profiles_profile_type_check CHECK (profile_type = ANY (ARRAY['user'::text, 'shop'::text]));
alter table public.profiles add constraint profiles_region_length CHECK (region IS NULL OR length(region) <= 80);
alter table public.profiles add constraint profiles_region_needs_country CHECK (region IS NULL OR country IS NOT NULL);
alter table public.profiles add constraint profiles_store_note_length CHECK (store_note IS NULL OR length(store_note) <= 180);
alter table public.profiles add constraint profiles_text_bounds CHECK (char_length(COALESCE(display_name, ''::text)) <= 80 AND char_length(COALESCE(bio, ''::text)) <= 1000 AND char_length(COALESCE(location, ''::text)) <= 120);
alter table public.profiles add constraint profiles_username_format CHECK (username IS NULL OR username ~ '^[a-z0-9_]{3,30}$'::text);
alter table public.profiles add constraint profiles_username_key UNIQUE (username);

